<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Auth,Request};
use App\Services\SimplePdfService;
final class ReportController extends Controller {
    public function index(): void {if(!Auth::can('report.view')){$this->forbidden();return;}$db=Database::connection();$t=Auth::tenantId();$from=Request::input('from',date('Y-m-01'));$to=Request::input('to',date('Y-m-t'));$jobStatus=$this->query($db,"SELECT status label,COUNT(*) value FROM jobs WHERE tenant_id=? AND deleted_at IS NULL AND DATE(created_at) BETWEEN ? AND ? GROUP BY status ORDER BY value DESC",[$t,$from,$to]);$categories=$this->query($db,"SELECT COALESCE(service_category,'Uncategorized') label,COUNT(*) value FROM jobs WHERE tenant_id=? AND deleted_at IS NULL AND DATE(created_at) BETWEEN ? AND ? GROUP BY service_category ORDER BY value DESC LIMIT 10",[$t,$from,$to]);$tech=$this->query($db,"SELECT u.name label,COUNT(DISTINCT j.id) jobs,SUM(CASE WHEN j.status IN('Completed','Closed') THEN 1 ELSE 0 END) completed FROM job_technicians jt JOIN users u ON u.id=jt.user_id AND u.tenant_id=jt.tenant_id JOIN jobs j ON j.id=jt.job_id AND j.tenant_id=jt.tenant_id WHERE jt.tenant_id=? AND DATE(j.created_at) BETWEEN ? AND ? GROUP BY u.id,u.name ORDER BY completed DESC",[$t,$from,$to]);$customers=$this->query($db,"SELECT c.name label,COALESCE(SUM(i.total),0) revenue,COUNT(DISTINCT j.id) jobs FROM customers c LEFT JOIN invoices i ON i.customer_id=c.id AND i.tenant_id=c.tenant_id AND i.status<>'Cancelled' AND i.invoice_date BETWEEN ? AND ? LEFT JOIN jobs j ON j.customer_id=c.id AND j.tenant_id=c.tenant_id AND DATE(j.created_at) BETWEEN ? AND ? WHERE c.tenant_id=? AND c.deleted_at IS NULL GROUP BY c.id,c.name ORDER BY revenue DESC LIMIT 10",[$from,$to,$from,$to,$t]);$monthly=$this->query($db,"SELECT DATE_FORMAT(payment_date,'%Y-%m') month,SUM(amount) revenue FROM payments WHERE tenant_id=? AND payment_date>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY DATE_FORMAT(payment_date,'%Y-%m') ORDER BY month",[$t]);$scalar=function(string $sql,array $a)use($db){$s=$db->prepare($sql);$s->execute($a);return $s->fetchColumn();};$totalJobs=(int)$scalar("SELECT COUNT(*) FROM jobs WHERE tenant_id=? AND deleted_at IS NULL AND DATE(created_at) BETWEEN ? AND ?",[$t,$from,$to]);$completed=(int)$scalar("SELECT COUNT(*) FROM jobs WHERE tenant_id=? AND deleted_at IS NULL AND status IN('Completed','Closed') AND DATE(created_at) BETWEEN ? AND ?",[$t,$from,$to]);$slaTotal=(int)$scalar("SELECT COUNT(*) FROM service_requests WHERE tenant_id=? AND deleted_at IS NULL AND resolution_deadline IS NOT NULL AND request_date BETWEEN ? AND ?",[$t,$from,$to]);$slaBreach=(int)$scalar("SELECT COUNT(*) FROM service_requests WHERE tenant_id=? AND deleted_at IS NULL AND resolution_deadline IS NOT NULL AND request_date BETWEEN ? AND ? AND ((status NOT IN('Completed','Closed','Cancelled') AND resolution_deadline<NOW()) OR (status IN('Completed','Closed') AND updated_at>resolution_deadline))",[$t,$from,$to]);$quotes=(int)$scalar("SELECT COUNT(*) FROM quotations WHERE tenant_id=? AND deleted_at IS NULL AND quotation_date BETWEEN ? AND ?",[$t,$from,$to]);$approved=(int)$scalar("SELECT COUNT(*) FROM quotations WHERE tenant_id=? AND deleted_at IS NULL AND status='Approved' AND quotation_date BETWEEN ? AND ?",[$t,$from,$to]);$revenue=(float)$scalar("SELECT COALESCE(SUM(amount),0) FROM payments WHERE tenant_id=? AND payment_date BETWEEN ? AND ?",[$t,$from,$to]);$expenses=(float)$scalar("SELECT COALESCE(SUM(amount),0) FROM job_expenses WHERE tenant_id=? AND expense_date BETWEEN ? AND ?",[$t,$from,$to]);$matCost=(float)$scalar("SELECT COALESCE(SUM(jm.quantity*jm.unit_cost),0) FROM job_materials jm JOIN jobs j ON j.id=jm.job_id AND j.tenant_id=jm.tenant_id WHERE jm.tenant_id=? AND DATE(j.created_at) BETWEEN ? AND ?",[$t,$from,$to]);$inventory=(float)$scalar("SELECT COALESCE(SUM(sb.quantity*i.purchase_price),0) FROM stock_balances sb JOIN items i ON i.id=sb.item_id AND i.tenant_id=sb.tenant_id WHERE sb.tenant_id=?",[$t]);$kpi=['jobs'=>$totalJobs,'completion_rate'=>$totalJobs?round($completed/$totalJobs*100,1):0,'sla_compliance'=>$slaTotal?round(($slaTotal-$slaBreach)/$slaTotal*100,1):100,'quote_conversion'=>$quotes?round($approved/$quotes*100,1):0,'revenue'=>$revenue,'expenses'=>$expenses+$matCost,'gross_profit'=>$revenue-$expenses-$matCost,'inventory_value'=>$inventory];$this->view('reports/index',['title'=>'Report Center','from'=>$from,'to'=>$to,'kpi'=>$kpi,'jobStatus'=>$jobStatus,'categories'=>$categories,'tech'=>$tech,'customers'=>$customers,'monthly'=>$monthly]);}
    public function exportJobs(): never {if(!Auth::can('report.view')){http_response_code(403);exit;}$db=Database::connection();$t=Auth::tenantId();$from=Request::input('from',date('Y-m-01'));$to=Request::input('to',date('Y-m-t'));$rows=$this->query($db,"SELECT j.job_number,c.name customer,j.service_category,j.priority,j.scheduled_date,j.status,j.started_at,j.completed_at FROM jobs j JOIN customers c ON c.id=j.customer_id AND c.tenant_id=j.tenant_id WHERE j.tenant_id=? AND j.deleted_at IS NULL AND DATE(j.created_at) BETWEEN ? AND ? ORDER BY j.id",[$t,$from,$to]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="jobs-report-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Job Number','Customer','Category','Priority','Scheduled','Status','Started','Completed']);foreach($rows as $r)fputcsv($out,array_values($r));fclose($out);exit;}
    public function exportJobsExcel(): never {
        if(!Auth::can('report.view')){http_response_code(403);exit;}$db=Database::connection();$t=Auth::tenantId();$from=Request::input('from',date('Y-m-01'));$to=Request::input('to',date('Y-m-t'));
        $rows=$this->query($db,"SELECT j.job_number,c.name customer,j.service_category,j.priority,j.scheduled_date,j.status,j.started_at,j.completed_at FROM jobs j JOIN customers c ON c.id=j.customer_id AND c.tenant_id=j.tenant_id WHERE j.tenant_id=? AND j.deleted_at IS NULL AND DATE(j.created_at) BETWEEN ? AND ? ORDER BY j.id",[$t,$from,$to]);
        header('Content-Type: application/vnd.ms-excel; charset=utf-8');header('Content-Disposition: attachment; filename="jobs-report-'.$from.'-'.$to.'.xls"');header('X-Content-Type-Options: nosniff');
        echo "\xEF\xBB\xBF<table border=\"1\"><thead><tr>";foreach(['Job Number','Customer','Category','Priority','Scheduled','Status','Started','Completed'] as $h)echo '<th>'.htmlspecialchars($h,ENT_QUOTES,'UTF-8').'</th>';echo '</tr></thead><tbody>';
        foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8').'</td>';echo '</tr>';}echo '</tbody></table>';exit;
    }
    public function exportSummaryPdf(): never {
        if(!Auth::can('report.view')){http_response_code(403);exit;}$db=Database::connection();$t=Auth::tenantId();$from=Request::input('from',date('Y-m-01'));$to=Request::input('to',date('Y-m-t'));
        $scalar=function(string $sql,array $a)use($db){$s=$db->prepare($sql);$s->execute($a);return $s->fetchColumn();};
        $jobs=(int)$scalar("SELECT COUNT(*) FROM jobs WHERE tenant_id=? AND deleted_at IS NULL AND DATE(created_at) BETWEEN ? AND ?",[$t,$from,$to]);$completed=(int)$scalar("SELECT COUNT(*) FROM jobs WHERE tenant_id=? AND deleted_at IS NULL AND status IN('Completed','Closed') AND DATE(created_at) BETWEEN ? AND ?",[$t,$from,$to]);$revenue=(float)$scalar("SELECT COALESCE(SUM(amount),0) FROM payments WHERE tenant_id=? AND payment_date BETWEEN ? AND ?",[$t,$from,$to]);$expense=(float)$scalar("SELECT COALESCE(SUM(amount),0) FROM job_expenses WHERE tenant_id=? AND expense_date BETWEEN ? AND ?",[$t,$from,$to]);$material=(float)$scalar("SELECT COALESCE(SUM(jm.quantity*jm.unit_cost),0) FROM job_materials jm JOIN jobs j ON j.id=jm.job_id AND j.tenant_id=jm.tenant_id WHERE jm.tenant_id=? AND DATE(j.created_at) BETWEEN ? AND ?",[$t,$from,$to]);
        $tenant=$db->prepare("SELECT name,logo,invoice_footer FROM tenants WHERE id=?");$tenant->execute([$t]);$company=$tenant->fetch()?:['name'=>'ServicePro'];
        $status=$this->query($db,"SELECT status,COUNT(*) total FROM jobs WHERE tenant_id=? AND deleted_at IS NULL AND DATE(created_at) BETWEEN ? AND ? GROUP BY status ORDER BY total DESC",[$t,$from,$to]);
        $lines=['REPORT PERIOD: '.$from.' to '.$to,'','EXECUTIVE SUMMARY','Total Jobs: '.$jobs,'Completed / Closed: '.$completed,'Completion Rate: '.($jobs?number_format($completed/$jobs*100,1):'0.0').'%','Revenue Collected: '.money($revenue),'Job Expenses: '.money($expense),'Material Cost: '.money($material),'Gross Profit: '.money($revenue-$expense-$material),'','JOB STATUS'];foreach($status as $r)$lines[]=$r['status'].': '.$r['total'];
        SimplePdfService::output('management-report-'.$from.'-'.$to.'.pdf',$lines,($company['name']??'ServicePro').' - Management Report',['logo_path'=>$company['logo']??null,'footer'=>$company['invoice_footer']??null]);
    }
    private function query(\PDO $db,string $sql,array $a):array{$s=$db->prepare($sql);$s->execute($a);return $s->fetchAll();}private function forbidden():void{http_response_code(403);require BASE_PATH.'/app/Views/errors/403.php';}
}
